#!/usr/bin/env python3
"""Generate go/SKILL.md and agents/v-agent.md from agents/references/ (single source)."""

from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
COMM = ROOT / "agents" / "references" / "communication-system-prompt.md"
GATE = ROOT / "agents" / "references" / "poteto-gate.md"
GO_OUT = ROOT / "skills" / "go" / "SKILL.md"
VAGENT_OUT = ROOT / "agents" / "v-agent.md"

GENERATED_BANNER = (
    "<!-- Generated by scripts/build_entry_skills.py. Edit agents/references/ "
    "then re-run the script. Do not edit this file by hand. -->"
)


def nest_code_fences(text: str) -> str:
    """Keep citation examples valid inside the generated markdown file."""
    # The communication prompt shows a fenced citation example; wrap it so the
    # outer SKILL.md fence structure stays valid when we embed the whole prompt.
    old = (
        "```12:15:app/components/Todo.tsx\n"
        "// ... existing code ...\n"
        "```"
    )
    new = (
        "````\n"
        "```12:15:app/components/Todo.tsx\n"
        "// ... existing code ...\n"
        "```\n"
        "````"
    )
    return text.replace(old, new)


def strip_gate_go_section(gate: str) -> str:
    """Drop the `/go` section from poteto-gate when embedding into go itself."""
    marker = "\n## `/go`\n"
    if marker in gate:
        return gate.split(marker, 1)[0].rstrip() + "\n"
    return gate


def build_go(comm: str, gate: str) -> str:
    gate_body = strip_gate_go_section(gate)
    # poteto-gate starts with "# Poteto gate"; keep as ## under go
    if gate_body.startswith("# "):
        gate_body = "## " + gate_body[2:]
    gate_body = gate_body.replace("\n## ", "\n### ").replace(
        "Apply the communication system prompt on every turn.",
        "Apply the communication rules above on every turn.",
    )
    return f"""---
name: go
description: >-
  One-shot entry matching the v-agent plugin agent: communication rules and
  poteto gate. For a full session, select v-agent in Agents instead.
---

{GENERATED_BANNER}

# go

`/go` matches **v-agent** for this message. Apply the sections below **verbatim** — do not open external reference files.

For ongoing sessions, select **v-agent** in the Agents picker (Cursor / Claude). On Codex, pi, and omp, invoke `/go` or the `go` skill each turn that needs the gate.

## Communication

{nest_code_fences(comm).rstrip()}

{gate_body.rstrip()}
"""


def build_vagent(comm: str, gate: str) -> str:
    gate_body = gate
    if gate_body.startswith("# "):
        gate_body = "## " + gate_body[2:]
    return f"""---
name: v-agent
description: >-
  Default estack persona and communication gate. Apply the bundled communication
  system prompt on every reply, then route non-trivial engineering work through
  poteto-mode (estack). Select v-agent in Agents, or use /go for one-shot entry.
---

{GENERATED_BANNER}

# v-agent

You are **v-agent**, the estack entry persona. Your job is to talk to the user the way the bundled system prompt specifies, and to hand off engineering rigor to **poteto-mode** when the task needs it.

Apply the sections below **verbatim** on every turn — do not open external reference files.

## Poteto workflows

Non-trivial engineering work routes to the **`poteto-mode`** skill in this plugin. When the gate says poteto-mode, read that skill in full. If it is missing from the session, follow the fallback in the Poteto gate section below.

## Identity

Do not introduce yourself as a named third-party model. Follow the identity lines in the communication section.

## Communication

{nest_code_fences(comm).rstrip()}

{gate_body.rstrip()}
"""


def main() -> int:
    if not COMM.is_file() or not GATE.is_file():
        raise SystemExit(f"Missing sources: {COMM} or {GATE}")
    comm = COMM.read_text(encoding="utf-8")
    gate = GATE.read_text(encoding="utf-8")
    GO_OUT.parent.mkdir(parents=True, exist_ok=True)
    GO_OUT.write_text(build_go(comm, gate) + "\n", encoding="utf-8")
    VAGENT_OUT.write_text(build_vagent(comm, gate) + "\n", encoding="utf-8")
    print(f"Wrote {GO_OUT.relative_to(ROOT)}")
    print(f"Wrote {VAGENT_OUT.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
